        receivedAt: e.receivedAt,
        eventName: e.eventName,
        eventNameConfirmed: e.eventNameConfirmed,
        sessionId: e.sessionId,
        agentId: e.agentId,
        isMainThread: e.isMainThread,
        toolUseId: e.toolUseId,
        toolName: e.toolName,
        raw: e.raw,
      })}\n`);
    },
  });

