        + 'Free the port (disable/stop the extension, or close that window) and re-run. '
        + 'Binding a different port is NOT a fix.',
      );
    }
    throw err;
  }

  return {
    port,
    get count() { return count; },
    get byEvent() { return { ...byEvent }; },
    async stop() {
      await listener.stop();
      await new Promise((res) => stream.end(res));
      return { count, byEvent: { ...byEvent } };
    },
  };
}

