function forWslpath(windowsPath: string): string {
  return windowsPath.replace(/\\/g, '/');
}

function detectWsl(): WslAvailability {
  if (process.platform !== 'win32') {
    return { usable: false, reason: `host platform is ${process.platform}, not win32` };
  }
  try {
    wsl(['true']);
  } catch (error) {
    return { usable: false, reason: `wsl.exe is not usable: ${String(error).split('\n')[0]}` };
  }
  const override = process.env['AGENT_DECK_WSL_NODE'];
  for (const candidate of override === undefined ? LINUX_NODE_CANDIDATES : [override]) {
    try {
      // `command -v` resolves PATH entries and expands $HOME; the result is an
      // absolute path we can exec without a shell.
      const resolved = wsl(['sh', '-c', `command -v "${candidate}"`]);
      if (resolved === '') continue;
      // WSL's PATH includes the Windows one, so a candidate can resolve to a
      // Windows binary through interop. Only a Linux Node counts as the leg.
      const platform = wsl([resolved, '-e', 'process.stdout.write(process.platform)']);
      if (platform === 'linux') return { usable: true, reason: '', linuxNode: resolved };
    } catch {
      // try the next candidate
    }
  }
  return {
    usable: false,
    reason:
      'WSL is present but has no Linux Node. Restore it with:\n' +
      "  wsl.exe -- bash -lc 'mkdir -p ~/.local/opt && cd ~/.local/opt && " +
      'curl -sSLO https://nodejs.org/dist/v24.19.0/node-v24.19.0-linux-x64.tar.xz && ' +
      "tar xf node-v24.19.0-linux-x64.tar.xz'\n" +
      '  or point AGENT_DECK_WSL_NODE at any Linux node binary.',
  };
}

const WSL = detectWsl();

// Builds lab/codex-hooks.json — the block the USER pastes into ~/.codex/hooks.json.
// Claude never writes ~/.codex (G1 names hooks.json and config.toml explicitly).
//
// The POST command is EXTRACTED from the shipped CC README block, never retyped:
// the whole point of the narrowing is that the harvest pins what the shipped block
// delivers to the shipped listener. A transcription typo would silently break that.
//
// Six events, matching the CC block exactly:
//   SessionStart PreToolUse PostToolUse SubagentStart SubagentStop Stop
// The other five Codex events (PermissionRequest, SessionEnd, PreCompact,
// PostCompact, UserPromptSubmit) are dropped: the engine consumes none of them.
//
// Codex's schema differs from CC's: no "matcher" key, and each hook carries a
// "commandWindows" twin. Structure is taken from the file currently installed.
import fs from 'node:fs';

const README = new URL('../../README.md', import.meta.url);
const OUT = new URL('../codex-hooks.json', import.meta.url);

const readme = fs.readFileSync(README, 'utf8');

// Pull every `"command": "node -e \"...\""` line out of the fenced block and
// require them to be identical — if the README ever ships two variants, this
// stops rather than silently picking one.
const matches = [...readme.matchAll(/^\s*"command": "(node -e .*)",?$/gm)].map((m) => m[1]);
if (matches.length === 0) throw new Error('no node -e command found in README.md');
const distinct = [...new Set(matches)];
if (distinct.length !== 1) throw new Error(`README has ${distinct.length} distinct hook commands; expected 1`);

// The captured group is the JSON *source* form (backslash-escaped). Decode it to
// the real string, then let JSON.stringify re-escape it on the way out.
const command = JSON.parse(`"${distinct[0]}"`);

if (!command.includes('127.0.0.1')) throw new Error('command lost its loopback host');
if (!command.includes('47821')) throw new Error('command lost port 47821');
if (!command.includes('/event')) throw new Error('command lost the /event path');

const EVENTS = ['SessionStart', 'PreToolUse', 'PostToolUse', 'SubagentStart', 'SubagentStop', 'Stop'];

const hooks = {};
for (const ev of EVENTS) {
  hooks[ev] = [{ hooks: [{ type: 'command', command, commandWindows: command }] }];
}

const doc = { hooks };
fs.writeFileSync(OUT, `${JSON.stringify(doc, null, 2)}\n`, 'utf8');

console.log(`README hook commands found: ${matches.length}, distinct: ${distinct.length}`);
